<details class="panel"><summary>Administrator block controls</summary><p>New programme task allocations use sequence control. Existing task sets keep their previous access until an administrator enables it here. Each later block needs all five source tasks approved in every previous block. Exceptions release only the selected block; they do not approve previous tasks or KSBs. Turning control off opens all existing task blocks. Saved work is retained.</p><form method="post" action="{{ route('blocks.control',$apprentice) }}">@csrf<input name="version" type="hidden" value="{{ $blockControl?->version??0 }}"><div class="form-grid"><div><label for="sequence-enabled">Sequence control</label><select id="sequence-enabled" name="enabled"><option value="1" @selected($blockControl?->enabled)>Enabled</option><option value="0" @selected(!$blockControl?->enabled)>Disabled</option></select></div><div><label for="sequence-operation">Change</label><select id="sequence-operation" name="operation"><option value="settings">Save sequence setting</option><option value="release">Release a block as an exception</option><option value="withdraw">Withdraw a block exception</option></select></div><div><label for="sequence-block">Block (exceptions only)</label><select id="sequence-block" name="block"><option value="">Choose</option>@foreach(range(2,10) as $number)<option>{{ $number }}</option>@endforeach</select></div><div><label for="sequence-reason">Reason</label><textarea id="sequence-reason" name="reason" required maxlength="2000"></textarea></div></div><button>Save block controls</button></form><h3>Recorded changes</h3>@forelse(array_reverse($blockControl?->history??[]) as $change)<p>{{ $change['at'] }} · {{ str_replace('_',' ',$change['event']) }} · {{ $change['reason']??'Sequence enabled for new allocation' }} @if($change['block']??null) · Block {{ $change['block'] }} @endif</p>@empty<p>No block-control changes recorded.</p>@endforelse</details>